
begin;
create table sim_murid_private.report_snapshots(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id),class_id uuid not null references public.classes(id),academic_year_id uuid not null references public.academic_years(id),semester integer not null check(semester in(1,2)),snapshot jsonb not null,published_by uuid not null references public.profiles(id),published_at timestamptz not null default now(),unique(student_id,class_id,academic_year_id,semester));
create index report_student on sim_murid_private.report_snapshots(student_id);
create trigger report_immutable before update or delete on sim_murid_private.report_snapshots for each row execute function sim_murid_private.deny_mutation();
create function public.app_report_draft(p_actor uuid,p_session uuid,p_student uuid,p_class uuid,p_semester integer) returns jsonb language plpgsql stable security invoker set search_path='' as $$declare y uuid;r jsonb;begin
 if not public.app_onboarding_ready(p_actor,p_session) then return null;end if;
 if not(public.app_ops_student(p_actor,p_session,p_student) or exists(select 1 from public.classes where id=p_class and homeroom_teacher_id=p_actor) or exists(select 1 from sim_murid_private.lesson_schedules l where l.class_id=p_class and l.teacher_id=p_actor and l.archived_at is null and public.app_onboarding_ready(p_actor,p_session))) then return null;end if;
 select academic_year_id into y from public.classes where id=p_class;if y is null or p_semester not in(1,2) or not exists(select 1 from sim_murid_private.enrollments where student_id=p_student and class_id=p_class and academic_year_id=y) then return null;end if;
 select coalesce(jsonb_agg(to_jsonb(q)||jsonb_build_object('grade',case when q.final<q.kkm then 'D' when q.final>=q.kkm+(100-q.kkm)*2/3 then 'A' when q.final>=q.kkm+(100-q.kkm)/3 then 'B' else 'C' end) order by q.sort_order),'[]') into r from(
 select sb.id as subject_id,sb.name,sb.sort_order,coalesce(k.value,75)kkm,k.value is null as kkm_fallback,avg(sc.value) filter(where a.kind='PH')ph,max(sc.value) filter(where a.kind='ATS')ats,max(sc.value) filter(where a.kind='ASAS')asas,max(sc.value) filter(where a.kind='Praktik')practice,
 round(coalesce(avg(sc.value) filter(where a.kind='PH'),0)*.2+coalesce(max(sc.value) filter(where a.kind='ATS'),0)*.3+coalesce(max(sc.value) filter(where a.kind='ASAS'),0)*.5,2) final,
 coalesce(jsonb_agg(jsonb_build_object('assessment_id',a.id,'kind',a.kind,'ph_number',a.ph_number,'value',sc.value,'kkm',a.kkm_snapshot,'kkm_fallback',a.kkm_fallback)) filter(where a.id is not null),'[]') sources,
 count(sc.value) filter(where a.kind='PH')>0 and count(sc.value) filter(where a.kind='ATS')>0 and count(sc.value) filter(where a.kind='ASAS')>0 complete
 from public.subjects sb left join sim_murid_private.assessments a on a.subject_id=sb.id and a.class_id=p_class and a.academic_year_id=y and a.semester=p_semester and a.voided_at is null left join sim_murid_private.assessment_scores sc on sc.assessment_id=a.id and sc.student_id=p_student left join sim_murid_private.minimum_grades k on k.class_id=p_class and k.subject_id=sb.id and k.academic_year_id=y and k.semester=p_semester
 where sb.active and (exists(select 1 from sim_murid_private.lesson_schedules where class_id=p_class and subject_id=sb.id and archived_at is null) or exists(select 1 from sim_murid_private.assessments where class_id=p_class and subject_id=sb.id and voided_at is null)) and (public.app_ops_student(p_actor,p_session,p_student) or exists(select 1 from public.classes where id=p_class and homeroom_teacher_id=p_actor) or public.app_teaching_access(p_actor,p_session,p_class,sb.id,false)) group by sb.id,k.value)q;
 return jsonb_build_object('student',(select jsonb_build_object('id',id,'name',full_name,'username',username) from public.profiles where id=p_student),'class',(select jsonb_build_object('id',id,'name',name) from public.classes where id=p_class),'year',(select start_year from public.academic_years where id=y),'semester',p_semester,'policy','RAPOR-1.0','subjects',r,'school',(select jsonb_build_object('name',name,'address',address_data,'identity',identity_data) from public.school_profile),'draft',true);end$$;
do $$declare t text;r record;begin foreach t in array array['report_snapshots'] loop execute format('alter table sim_murid_private.%I enable row level security',t);execute format('revoke all on sim_murid_private.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on sim_murid_private.%I to service_role',t);end loop;for r in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('app_report_draft') loop execute format('revoke all on function %s from public,anon,authenticated',r.signature);execute format('grant execute on function %s to service_role',r.signature);end loop;end$$;
commit;
